def match_parens(lst):
    if len(lst[0]) + len(lst[1]) > 1000:
        return 'No'

    open_count = 0
    for char in lst[0] + lst[1]:
        if char == '(':
            open_count += 1
        elif char == ')':
            if open_count == 0:
                return 'No'
            open_count -= 1

    if open_count == 0:
        return 'Yes'
    else:
        return 'No'

